    14→
    15→class CreateRoomScreenViewModel: CreateRoomScreenViewModelType, CreateRoomScreenViewModelProtocol {
    16→    private let userSession: UserSessionProtocol
    17→    private let mediaUploadingPreprocessor: MediaUploadingPreprocessor
    18→    private let analytics: AnalyticsService
    19→    private let userIndicatorController: UserIndicatorControllerProtocol
    20→    
    21→    private var syncNameAndAlias = true
    22→    @CancellableTask private var checkAliasAvailabilityTask: Task<Void, Never>?
    23→    
    24→    private var actionsSubject: PassthroughSubject<CreateRoomScreenViewModelAction, Never> = .init()
    25→    
    26→    var actions: AnyPublisher<CreateRoomScreenViewModelAction, Never> {
    27→        actionsSubject.eraseToAnyPublisher()
    28→    }
    29→    
    30→    init(isSpace: Bool,
    31→         spaceSelectionMode: CreateRoomScreenSpaceSelectionMode,
    32→         shouldShowCancelButton: Bool,
    33→         userSession: UserSessionProtocol,
    34→         analytics: AnalyticsService,
    35→         userIndicatorController: UserIndicatorControllerProtocol,
    36→         appSettings: AppSettings) {
    37→        self.userSession = userSession
    38→        mediaUploadingPreprocessor = MediaUploadingPreprocessor(appSettings: appSettings)
    39→        self.analytics = analytics
    40→        self.userIndicatorController = userIndicatorController
    41→        
    42→        var selectedSpace: SpaceServiceRoom?
    43→        let canSelectSpace: Bool
    44→        var selectedAccessType = CreateRoomScreenAccessType.private
    45→        switch spaceSelectionMode {
    46→        case .editableSpacesList(let preSelectedSpace):
    47→            canSelectSpace = true
    48→            if let preSelectedSpace {
    49→                selectedSpace = preSelectedSpace
    50→                if preSelectedSpace.joinRule != .public {
    51→                    selectedAccessType = .spaceMembers
    52→                }
    53→            }
    54→        case .none:
    55→            canSelectSpace = false
    56→        }
    57→        
    58→        let bindings = CreateRoomScreenViewStateBindings(roomTopic: "",
    59→                                                         selectedAccessType: selectedAccessType,
    60→                                                         selectedSpace: selectedSpace)
    61→
    62→        super.init(initialViewState: CreateRoomScreenViewState(isSpace: isSpace,
    63→                                                               shouldShowCancelButton: shouldShowCancelButton,
    64→                                                               roomName: "",
    65→                                                               serverName: userSession.clientProxy.userIDServerName ?? "",
    66→                                                               isKnockingFeatureEnabled: appSettings.knockingEnabled,
    67→                                                               canSelectSpace: canSelectSpace,
    68→                                                               aliasLocalPart: roomAliasNameFromRoomDisplayName(roomName: ""),
    69→                                                               bindings: bindings),
    70→                   mediaProvider: userSession.mediaProvider)
    71→        
    72→        setupBindings()
    73→        
    74→        if canSelectSpace {
    75→            Task {
    76→                state.editableSpaces = await userSession.clientProxy.spaceService.editableSpaces()
    77→            }
    78→        }
    79→    }
