    81→    // MARK: - Public
    82→    
    83→    override func process(viewAction: CreateRoomScreenViewAction) {
    84→        switch viewAction {
    85→        case .dismiss:
    86→            actionsSubject.send(.dismiss)
    87→        case .createRoom:
    88→            Task { await createRoom() }
    89→        case .displayCameraPicker:
    90→            actionsSubject.send(.displayCameraPicker)
    91→        case .displayMediaPicker:
    92→            actionsSubject.send(.displayMediaPicker)
    93→        case .removeImage:
    94→            state.avatarMediaInfo = nil
    95→        case .updateAliasLocalPart(let aliasLocalPart):
    96→            state.aliasLocalPart = aliasLocalPart.lowercased()
    97→            // If this has been called this means that the user wants a custom address not necessarily reflecting the name
    98→            // So we disable the two from syncing.
    99→            syncNameAndAlias = false
   100→        case .updateRoomName(let name):
   101→            // Reset the syncing if the name is fully cancelled
   102→            if name.isEmpty {
   103→                syncNameAndAlias = true
   104→            }
   105→            state.roomName = name
   106→            if syncNameAndAlias {
   107→                state.aliasLocalPart = roomAliasNameFromRoomDisplayName(roomName: name)
   108→            }
   109→        }
   110→    }
