   112→    func updateAvatar(fileURL: URL) {
   113→        showLoadingIndicator()
   114→        Task { [weak self] in
   115→            guard let self else { return }
   116→            do {
   117→                guard case let .success(maxUploadSize) = await userSession.clientProxy.maxMediaUploadSize else {
   118→                    MXLog.error("Failed to get max upload size")
   119→                    state.bindings.alertInfo = .init(id: .unknown)
   120→                    return
   121→                }
   122→                let mediaInfo = try await mediaUploadingPreprocessor.processMedia(at: fileURL, maxUploadSize: maxUploadSize).get()
   123→                
   124→                switch mediaInfo {
   125→                case .image:
   126→                    state.avatarMediaInfo = mediaInfo
   127→                default:
   128→                    break
   129→                }
   130→            } catch {
   131→                state.bindings.alertInfo = .init(id: .failedProcessingMedia)
   132→            }
   133→            hideLoadingIndicator()
   134→        }
   135→    }
