   137→    // MARK: - Private
   138→
   139→    private func setupBindings() {
   140→        // Reset the state related to public rooms if the user choses the room to be empty
   141→        context.$viewState
   142→            .dropFirst()
   143→            .map(\.roomAccessType)
   144→            .filter(\.isVisibilityPrivate)
   145→            .removeDuplicates()
   146→            .receive(on: DispatchQueue.main)
   147→            .sink { [weak self] _ in
   148→                guard let self else { return }
   149→                state.aliasErrors = []
   150→                state.aliasLocalPart = roomAliasNameFromRoomDisplayName(roomName: state.roomName)
   151→                syncNameAndAlias = true
   152→            }
   153→            .store(in: &cancellables)
   154→        
   155→        context.$viewState
   156→            .map(\.aliasLocalPart)
   157→            .removeDuplicates()
   158→            .debounce(for: 1, scheduler: DispatchQueue.main)
   159→            .sink { [weak self] aliasLocalPart in
   160→                guard let self else {
   161→                    return
   162→                }
   163→                
   164→                guard !state.roomAccessType.isVisibilityPrivate,
   165→                      let canonicalAlias = String.makeCanonicalAlias(aliasLocalPart: aliasLocalPart,
   166→                                                                     serverName: state.serverName) else {
   167→                    // While is empty or private room we don't change or display the error
   168→                    return
   169→                }
   170→                
   171→                if !isRoomAliasFormatValid(alias: canonicalAlias) {
   172→                    state.aliasErrors.insert(.invalidSymbols)
   173→                    // If the alias is invalid we don't need to check for availability
   174→                    state.aliasErrors.remove(.alreadyExists)
   175→                    checkAliasAvailabilityTask = nil
   176→                    return
   177→                }
   178→                
   179→                state.aliasErrors.remove(.invalidSymbols)
   180→                
   181→                checkAliasAvailabilityTask = Task { [weak self] in
   182→                    guard let self else {
   183→                        return
   184→                    }
   185→                    
   186→                    if case .success(false) = await self.userSession.clientProxy.isAliasAvailable(canonicalAlias) {
   187→                        guard !Task.isCancelled else { return }
   188→                        state.aliasErrors.insert(.alreadyExists)
   189→                    } else {
   190→                        guard !Task.isCancelled else { return }
   191→                        state.aliasErrors.remove(.alreadyExists)
   192→                    }
   193→                }
   194→            }
   195→            .store(in: &cancellables)
   196→        
   197→        context.$viewState
   198→            .map(\.availableAccessTypes)
   199→            .removeDuplicates()
   200→            .receive(on: DispatchQueue.main)
   201→            .sink { [weak self] availableAccessTypes in
   202→                guard let self else { return }
   203→                if !availableAccessTypes.contains(state.bindings.selectedAccessType) {
   204→                    state.bindings.selectedAccessType = .private
   205→                }
   206→            }
   207→            .store(in: &cancellables)
   208→    }
