   210→    private func createRoom() async {
   211→        defer {
   212→            hideLoadingIndicator()
   213→        }
   214→        showLoadingIndicator()
   215→        
   216→        // Better to double check the errors also when trying to create the room
   217→        if !state.roomAccessType.isVisibilityPrivate {
   218→            guard let canonicalAlias = String.makeCanonicalAlias(aliasLocalPart: state.aliasLocalPart,
   219→                                                                 serverName: state.serverName),
   220→                isRoomAliasFormatValid(alias: canonicalAlias) else {
   221→                state.aliasErrors = [.invalidSymbols]
   222→                return
   223→            }
   224→            
   225→            switch await userSession.clientProxy.isAliasAvailable(canonicalAlias) {
   226→            case .success(true):
   227→                break
   228→            case .success(false):
   229→                state.aliasErrors = [.alreadyExists]
   230→                return
   231→            case .failure:
   232→                state.bindings.alertInfo = AlertInfo(id: .unknown)
   233→                return
   234→            }
   235→        }
   236→        
   237→        let avatarURL: URL?
   238→        if let media = state.avatarMediaInfo {
   239→            switch await userSession.clientProxy.uploadMedia(media) {
   240→            case .success(let url):
   241→                avatarURL = URL(string: url)
   242→            case .failure(let error):
   243→                switch error {
   244→                case .failedUploadingMedia(let errorKind):
   245→                    switch errorKind {
   246→                    case .tooLarge:
   247→                        state.bindings.alertInfo = AlertInfo(id: .fileTooLarge)
   248→                    default:
   249→                        state.bindings.alertInfo = AlertInfo(id: .failedUploadingMedia)
   250→                    }
   251→                case .invalidMedia:
   252→                    state.bindings.alertInfo = AlertInfo(id: .mediaFileError)
   253→                default:
   254→                    state.bindings.alertInfo = AlertInfo(id: .unknown)
   255→                }
   256→                
   257→                return
   258→            }
   259→        } else {
   260→            avatarURL = nil
   261→        }
   262→        
   263→        switch await userSession.clientProxy.createRoom(name: state.roomName,
   264→                                                        topic: state.bindings.roomTopic.isBlank ? nil : state.bindings.roomTopic,
   265→                                                        accessType: state.roomAccessType,
   266→                                                        isSpace: state.isSpace,
   267→                                                        userIDs: [], // The invite users screen is shown next so we don't need to invite anyone right now.
   268→                                                        avatarURL: avatarURL,
   269→                                                        aliasLocalPart: state.roomAccessType.isVisibilityPrivate ? nil : state.aliasLocalPart) {
   270→        case .success(let roomID):
   271→            guard case let .joined(roomProxy) = await userSession.clientProxy.roomForIdentifier(roomID) else {
   272→                state.bindings.alertInfo = AlertInfo(id: .failedCreatingRoom,
   273→                                                     title: L10n.commonError,
   274→                                                     message: L10n.screenStartChatErrorStartingChat)
   275→                return
   276→            }
   277→            analytics.trackCreatedRoom(isDM: false)
   278→            
   279→            var spaceRoomListProxy: SpaceRoomListProxyProtocol?
   280→            if state.isSpace {
   281→                switch await userSession.clientProxy.spaceService.spaceRoomList(spaceID: roomID) {
   282→                case .success(let value):
   283→                    spaceRoomListProxy = value
   284→                case .failure:
   285→                    MXLog.error("Failed to get space room list for newly created space with id: \(roomID)")
   286→                    userIndicatorController.submitIndicator(.init(title: L10n.errorUnknown))
   287→                }
   288→            }
   289→            
   290→            if let spaceID = state.bindings.selectedSpace?.id {
   291→                await addRoomToSpace(roomProxy: roomProxy, spaceID: spaceID)
   292→            }
   293→            
   294→            actionsSubject.send(.createdRoom(roomProxy, spaceRoomListProxy))
   295→        case .failure:
   296→            state.bindings.alertInfo = AlertInfo(id: .failedCreatingRoom,
   297→                                                 title: L10n.commonError,
   298→                                                 message: L10n.screenStartChatErrorStartingChat)
   299→        }
   300→    }
   301→    
   302→    private func addRoomToSpace(roomProxy: JoinedRoomProxyProtocol, spaceID: String) async {
   303→        roomProxy.subscribeToRoomInfoUpdates()
   304→        let runner = ExpiringTaskRunner {
   305→            // Necessary to build the room cache so that the space can be added as a parent.
   306→            _ = await roomProxy.infoPublisher.values.first { $0.powerLevels != nil }
   307→        }
   308→        
   309→        do {
   310→            try await runner.run(timeout: .seconds(30))
   311→            if case .failure = await userSession.clientProxy.spaceService.addChild(roomProxy.id, to: spaceID) {
   312→                MXLog.error("Failed to add the created room with id: \(roomProxy.id) to the space with id: \(spaceID)")
   313→                userIndicatorController.submitIndicator(.init(title: L10n.errorUnknown))
   314→            }
   315→        } catch {
   316→            MXLog.error("Timed out waiting for power levels to load for room with id: \(roomProxy.id)")
   317→            userIndicatorController.submitIndicator(.init(title: L10n.errorUnknown))
   318→        }
   319→    }
   320→    
   321→    // MARK: Loading indicator
   322→    
   323→    private static let loadingIndicatorIdentifier = "\(CreateRoomScreenViewModel.self)-Loading"
   324→    
   325→    private func showLoadingIndicator() {
   326→        userIndicatorController.submitIndicator(UserIndicator(id: Self.loadingIndicatorIdentifier,
   327→                                                              type: .modal(progress: .indeterminate, interactiveDismissDisabled: true, allowsInteraction: false),
   328→                                                              title: L10n.commonLoading,
   329→                                                              persistent: true))
   330→    }
   331→    
   332→    private func hideLoadingIndicator() {
   333→        userIndicatorController.retractIndicatorWithId(Self.loadingIndicatorIdentifier)
   334→    }
   335→}
