    15→class InviteUsersScreenViewModel: InviteUsersScreenViewModelType, InviteUsersScreenViewModelProtocol {
    16→    private let roomProxy: JoinedRoomProxyProtocol
    17→    private let userDiscoveryService: UserDiscoveryServiceProtocol
    18→    private let userIndicatorController: UserIndicatorControllerProtocol
    19→    private let appSettings: AppSettings
    20→    
    21→    private var suggestedUsers = [UserProfileProxy]()
    22→    
