    24→    var actions: AnyPublisher<InviteUsersScreenViewModelAction, Never> {
    25→        actionsSubject.eraseToAnyPublisher()
    26→    }
    27→    
    28→    init(userSession: UserSessionProtocol,
    29→         roomProxy: JoinedRoomProxyProtocol,
    30→         isSkippable: Bool,
    31→         userDiscoveryService: UserDiscoveryServiceProtocol,
    32→         userIndicatorController: UserIndicatorControllerProtocol,
    33→         appSettings: AppSettings) {
    34→        self.roomProxy = roomProxy
    35→        self.userDiscoveryService = userDiscoveryService
    36→        self.userIndicatorController = userIndicatorController
    37→        self.appSettings = appSettings
    38→        
    39→        super.init(initialViewState: InviteUsersScreenViewState(selectedUsers: [],
    40→                                                                isSkippable: isSkippable),
    41→                   mediaProvider: userSession.mediaProvider)
    42→                
    43→        setupSubscriptions()
    44→        fetchMembersIfNeeded()
    45→        
    46→        Task {
    47→            suggestedUsers = await userSession.clientProxy.recentConversationCounterparts()
    48→            
    49→            if state.usersSection.type == .suggestions {
    50→                state.usersSection = .init(type: .suggestions, users: suggestedUsers)
    51→            }
