    55→    // MARK: - Public
    56→    
    57→    override func process(viewAction: InviteUsersScreenViewAction) {
    58→        switch viewAction {
    59→        case .cancel:
    60→            actionsSubject.send(.dismiss)
    61→        case .proceed:
    62→            inviteUsers(state.selectedUsers.map(\.userID), roomProxy: roomProxy)
    63→        case .toggleUser(let user):
    64→            toggleUser(user)
    65→        }
    66→    }
    67→
    68→    // MARK: - Private
    69→    
    70→    private func toggleUser(_ user: UserProfileProxy) {
    71→        if state.selectedUsers.contains(user) {
    72→            state.selectedUsers.removeAll { $0.userID == user.userID }
    73→        } else {
    74→            state.selectedUsers.append(user)
    75→            withElementAnimation(.easeInOut) { state.bindings.selectedUsersPosition = user.userID }
    76→        }
    77→    }
