    79→    private func inviteUsers(_ users: [String], roomProxy: JoinedRoomProxyProtocol) {
    80→        if appSettings.enableKeyShareOnInvite {
    81→            showLoadingIndicator(title: L10n.screenRoomDetailsInvitePeoplePreparing, message: L10n.screenRoomDetailsInvitePeopleDontClose)
    82→        } else {
    83→            showLoadingIndicator()
    84→        }
    85→        
    86→        Task {
    87→            defer {
    88→                hideLoadingIndicator()
    89→                actionsSubject.send(.dismiss)
    90→            }
    91→            
    92→            let result: Result<Void, RoomProxyError> = await withTaskGroup(of: Result<Void, RoomProxyError>.self) { group in
    93→                for user in users {
    94→                    group.addTask {
    95→                        await roomProxy.invite(userID: user)
    96→                    }
    97→                }
    98→                
    99→                return await group.first { inviteResult in
   100→                    inviteResult.isFailure
   101→                } ?? .success(())
   102→            }
   103→            
   104→            guard case .failure = result else {
   105→                return
